extra_css:
/* theme: editorial-studio (2026-10-27) */
:root,:root:not(x){--bg:#faf7f2;--fg:#1a1a1a;--muted:#5d5a55;--line:#ddd6cb;--card:#fff;--soft:#f1ece3;--accent:#5b3fe6;--accent2:#f0643f}
@media (prefers-color-scheme:dark){:root{--bg:#faf7f2;--fg:#1a1a1a;--muted:#5d5a55;--line:#ddd6cb;--card:#fff;--soft:#f1ece3;--accent:#5b3fe6;--accent2:#f0643f}}
body{font-family:"Noto Sans JP","Hiragino Sans",sans-serif}
header{background:#faf7f2;border-bottom:1px solid #1a1a1a}
.logo,.hero h1,article h1,.sec-h,article h2,.picks-h,.next-h,aside .box-h{font-family:"Shippori Mincho B1","Hiragino Mincho ProN",serif;font-weight:800}
.logo{font-size:24px;letter-spacing:.04em}.logo span{color:#5b3fe6}
.gnav a{background:none;border-radius:0;border-bottom:2px solid transparent;padding:6px 10px;color:#1a1a1a}
.gnav a:hover,.gnav a.on{background:none;color:#5b3fe6;border-bottom-color:#5b3fe6}
.hero-img{border-radius:2px}
.hero h1{font-size:32px;letter-spacing:.02em}
.sec-h{border-bottom:1px solid #1a1a1a;box-shadow:0 3px 0 -1px #faf7f2,0 4px 0 -1px #1a1a1a}
.card{border:1px solid #1a1a1a;border-radius:2px;padding:16px}
.thumb{border-radius:0}
.card:hover{border-color:#1a1a1a;transform:none;box-shadow:6px 6px 0 #f0643f}
.tag{background:none;color:#5b3fe6;border:1px solid #5b3fe6;border-radius:0;letter-spacing:.06em}
article h1{font-size:30px}
article h2{background:none;border-left:0;border-top:3px solid #1a1a1a;border-radius:0;padding:12px 0 0;font-size:23px}
article h2::before{content:"";display:block;width:36px;height:4px;background:#f0643f;margin-bottom:8px}
article h3{border-bottom:1px solid #1a1a1a}
.eyecatch{border-radius:2px}
.lead,.toc,.shop,aside .box,.author{border:1px solid #1a1a1a;border-radius:2px}
.toc{border-top:4px solid #5b3fe6}
.note{border-left:4px solid #f0643f;border-radius:0;background:#fff}
.picks{border:1px solid #1a1a1a;border-radius:2px;box-shadow:6px 6px 0 #5b3fe622}
.next{border:1px solid #1a1a1a;border-radius:2px;background:#f1ece3}.next-h{color:#1a1a1a}
.avatar{background:#1a1a1a;border-radius:2px;font-family:"Shippori Mincho B1",serif}
aside .box-h{border-bottom:1px solid #1a1a1a}
.mini img{border-radius:0}.mini b{background:#f0643f;border-radius:0}
th{background:#f1ece3}
footer{background:#1a1a1a;color:#cfc8bc;border-top:0}footer a{color:#fff}

/* hero-base: 2026-10-27 トップの見せ場の共通部分 */
.hx{padding:24px 0 6px}.hx-eyebrow{font-size:13px;font-weight:700;letter-spacing:.08em;color:var(--accent);margin:0 0 8px}
.hx-h1{font-size:clamp(28px,5vw,46px);line-height:1.3;margin:0 0 14px}.hx-h1 em{font-style:normal;color:var(--accent)}
.hx-lead{color:var(--muted);font-size:15px;margin:0 0 22px;max-width:680px}
.hx-chips{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0 26px}.hx-chips a{text-decoration:none;font-size:13px;padding:5px 12px}
.hx-vs{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;margin:0 0 22px}.hx-vs p{margin:0;font-size:13px;color:var(--muted)}
.hx-k{font-size:12px;color:var(--muted)}.hx-v{font-size:clamp(20px,3.4vw,28px);font-weight:800;line-height:1.35;margin:4px 0}
.hx-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 22px}.hx-stats b{display:block;line-height:1.1;font-variant-numeric:tabular-nums}.hx-stats span{font-size:12px;color:var(--muted)}
.hx-steps{list-style:none;padding:0;margin:0 0 8px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.hx-steps strong{display:block;font-size:15px}.hx-steps span{font-size:12px;color:var(--muted)}
@media (max-width:560px){.hx-vs,.hx-steps{grid-template-columns:1fr}.hx-stats{gap:6px}.hx-mid{justify-self:center}.hx-vs{text-align:center}}
[data-seq]>*{opacity:0;transform:translateY(6px);transition:opacity .4s,transform .4s}[data-seq]>.on{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-seq]>*{opacity:1;transform:none;transition:none}}

/* hero: magazine-spread (2026-10-27) */
.hx-mag .hx-h1{font-family:"Shippori Mincho B1",serif;font-weight:800;font-size:clamp(30px,5.4vw,52px)}.hx-mag .hx-h1 em{color:#5b3fe6}
.hx-mag .hx-eyebrow{color:#f0643f;letter-spacing:.2em}
.hx-spread{display:grid;grid-template-columns:1fr 1.3fr;border-top:3px solid #1a1a1a;border-bottom:1px solid #1a1a1a;background:#fff}
.hx-sp-l{padding:18px 20px;border-right:1px solid #1a1a1a}.hx-sp-no{font-size:11px;letter-spacing:.3em;color:#f0643f;font-weight:700}
.hx-sp-t{font-family:"Shippori Mincho B1",serif;font-weight:800;font-size:26px;line-height:1.35;margin:8px 0}.hx-sp-l p{font-size:13px;color:#5d5a55;margin:0 0 12px}
.hx-go{display:inline-block;font-family:"Shippori Mincho B1",serif;font-weight:800;color:#1a1a1a;text-decoration:none;border-bottom:2px solid #f0643f}
.hx-six{margin:0;display:grid;grid-template-columns:1fr 1fr}.hx-six div{padding:12px 16px;border-bottom:1px solid #ddd6cb;border-left:1px solid #ddd6cb}
.hx-six dt{font-size:11px;letter-spacing:.15em;color:#5b3fe6;font-weight:700}.hx-six dd{margin:2px 0 0;font-family:"Shippori Mincho B1",serif;font-weight:700;font-size:15px}
.hx-mag .hx-chips{border-bottom:1px solid #1a1a1a;padding-bottom:14px}.hx-mag .hx-chips a{color:#1a1a1a;border:0;border-right:1px solid #ddd6cb;border-radius:0;padding:2px 14px 2px 2px}.hx-mag .hx-chips a:hover{color:#5b3fe6}
.hx-mag .hx-vs{border-top:1px solid #1a1a1a;border-bottom:1px solid #1a1a1a;padding:18px 0}
.hx-mag .hx-v{font-family:"Shippori Mincho B1",serif}.hx-mag .hx-side.on .hx-v{color:#5b3fe6}.hx-mag .hx-mid{font-family:"Shippori Mincho B1",serif;font-size:40px;color:#f0643f;font-weight:400}
.hx-mag .hx-stats div{border-left:1px solid #1a1a1a;padding:4px 14px}
.hx-mag .hx-stats b{font-family:"Shippori Mincho B1",serif;font-weight:800;font-size:clamp(40px,7vw,64px);color:#1a1a1a}
.hx-mag .hx-steps li{border-top:3px solid #1a1a1a;padding-top:8px}.hx-mag .hx-steps b{font-family:"Shippori Mincho B1",serif;color:#f0643f;font-size:14px}
.hx-mag .hx-steps strong{font-family:"Shippori Mincho B1",serif;font-size:20px}
@media (max-width:700px){.hx-spread{grid-template-columns:1fr}.hx-sp-l{border-right:0;border-bottom:1px solid #1a1a1a}}

/* article-base: 2026-10-27 記事ページの共通部分 */
.ax-time{display:inline-block;font-size:12px;margin-left:8px}
.ax-prog{position:fixed;left:0;right:0;top:0;height:4px;z-index:50;pointer-events:none}.ax-prog i{display:block;height:100%;width:0}
.toc li.now>a{font-weight:700}
.ax-tick{cursor:pointer}li.ax-tick{position:relative;padding-left:30px}ul>li.ax-tick{list-style:none}ul>li.ax-tick::marker{content:""!important}
li.ax-tick::before,tr.ax-tick td:first-child::before{content:"";position:absolute;left:4px;top:.45em;width:16px;height:16px;border:2px solid currentColor;border-radius:4px;opacity:.55}
.ax-tick.done{opacity:.55;text-decoration:line-through}li.ax-tick.done::after,tr.ax-tick.done td:first-child::after{content:"✓";position:absolute;left:7px;top:.05em;font-weight:800}
tr.ax-tick td:first-child{position:relative;padding-left:32px}tr.ax-tick td:first-child::before{left:8px;top:.6em}tr.ax-tick.done td:first-child::after{left:11px;top:.2em}
.ax-copy{display:block;margin:10px 0 0 auto;font:inherit;font-size:13px;font-weight:700;cursor:pointer}
@media print{.ax-prog,.ax-size,.ax-copy{display:none}}

/* article: magazine (2026-10-27) */
.ax-prog{height:3px;background:transparent}.ax-prog i{background:#1a1a1a}
.ax-time{font-size:11px;letter-spacing:.15em;color:#f0643f;border-left:1px solid #1a1a1a;padding-left:10px}
article h1{font-family:"Shippori Mincho B1",serif;font-weight:800;font-size:clamp(26px,3.6vw,34px);line-height:1.45;border-bottom:1px solid #1a1a1a;padding-bottom:12px}
.lead{border:0;border-top:3px solid #1a1a1a;border-bottom:1px solid #1a1a1a;border-radius:0;background:none;padding:12px 0;font-family:"Shippori Mincho B1",serif;font-size:15px}
.lead strong{font-size:0}.lead strong::before{content:"EDITOR'S NOTE";font-size:11px;letter-spacing:.3em;color:#f0643f;font-family:"Noto Sans JP",sans-serif}
.lead+p::first-letter{float:left;font-family:"Shippori Mincho B1",serif;font-weight:800;font-size:3.4em;line-height:.9;margin:.08em .12em 0 0;color:#5b3fe6}
.toc{counter-reset:mg;border:0;border-top:1px solid #1a1a1a;border-bottom:1px solid #1a1a1a;border-radius:0;background:none;padding:12px 0}.toc strong{font-size:0}.toc strong::before{content:"CONTENTS";font-size:11px;letter-spacing:.3em}
.toc ol{list-style:none;padding:0;columns:2;column-gap:24px}.toc li{counter-increment:mg;break-inside:avoid;padding:3px 0;font-family:"Shippori Mincho B1",serif}.toc li::before{content:counter(mg,decimal-leading-zero);font-size:11px;color:#f0643f;margin-right:8px;font-family:"Noto Sans JP",sans-serif}
.toc li.now a{color:#5b3fe6}
article{counter-reset:mz}article h2{counter-increment:mz;font-family:"Shippori Mincho B1",serif}
article h2::before{content:counter(mz,decimal-leading-zero)!important;display:block!important;width:auto!important;height:auto!important;background:none!important;font-size:42px;line-height:1;color:#ddd6cb;margin:0 0 4px!important}
article h2.ax-sum::before{content:"FIN"!important}
article ul li::marker{content:"— ";color:#f0643f}
@media (max-width:560px){.toc ol{columns:1}}

/* category-base: 2026-10-27 カテゴリページの共通部分 */
.cx-page .cards{counter-reset:none}
.cx-page .card{position:relative;animation:cxin .5s both;animation-delay:calc(var(--i,0)*60ms)}
@keyframes cxin{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.cx-page .card{animation:none}}
.cx-head{position:relative;margin:4px 0 6px}.cx-head h1{margin:0}
.cx-intro{margin:8px 0 0}
.cx-meter{display:flex;align-items:center;gap:10px;margin:12px 0 0;font-size:13px}.cx-meter span{white-space:nowrap}.cx-meter b{font-size:1.25em}
.cx-meter i{position:relative;flex:1;height:8px;border-radius:99px;overflow:hidden;max-width:240px}
.cx-meter i::after{content:"";position:absolute;left:0;top:0;bottom:0;background:var(--cxm,#888);width:var(--w,0);transition:width .9s ease}
.cx-sort{display:inline-flex;gap:4px;margin:12px 0 0}.cx-sort button{font:inherit;font-size:13px;padding:4px 12px;cursor:pointer}
.cx-badge{position:absolute;top:10px;right:10px;font-size:12px;font-weight:700;padding:2px 10px;z-index:2}
.cx-others{margin:18px 0 8px}.cx-others strong{display:block;font-size:13px;margin-bottom:8px}.cx-others div{display:flex;flex-wrap:wrap;gap:8px}
.cx-others a{text-decoration:none;font-size:14px;padding:5px 12px}.cx-others small{margin-left:6px;opacity:.7}

/* category: magazine-feature (2026-10-27) */
.cx-feature{display:grid;grid-template-columns:auto 1fr;gap:22px;border-top:3px solid #1a1a1a;border-bottom:1px solid #1a1a1a;padding:18px 0}
.cx-vol{border-right:1px solid #1a1a1a;padding-right:22px;text-align:center}.cx-vol small{display:block;font-size:10px;letter-spacing:.3em;color:#f0643f}
.cx-vol b{font-family:"Shippori Mincho B1",serif;font-weight:800;font-size:72px;line-height:1;color:#5b3fe6}
.cx-eye{font-size:11px;letter-spacing:.2em;color:#6b6358}
.cx-feature h1{font-family:"Shippori Mincho B1",serif;font-weight:800;font-size:clamp(34px,5vw,52px);line-height:1.2;margin:4px 0}
.cx-feature .cx-intro{font-family:"Shippori Mincho B1",serif;font-size:16px}
.cx-page{--cxm:#5b3fe6}.cx-meter i{background:#ece6dc;height:4px;border-radius:0}
.cx-sort button{background:none;border:0;border-bottom:2px solid transparent;color:#6b6358;padding:4px 6px;letter-spacing:.1em}.cx-sort button.on{color:#1a1a1a;border-color:#f0643f}
@media (min-width:700px){.cx-page .card:first-child{grid-column:1/-1;display:grid;grid-template-columns:1.2fr 1fr;gap:0 22px;align-items:start}
 .cx-page .card:first-child .thumb{grid-row:1/6;margin:0;height:100%;object-fit:cover}.cx-page .card:first-child h2{font-family:"Shippori Mincho B1",serif;font-size:24px}}
.cx-page .card h2{font-family:"Shippori Mincho B1",serif}
.cx-page .card::before{content:attr(data-no);position:absolute;top:10px;left:10px;z-index:2;font-family:"Shippori Mincho B1",serif;font-weight:800;font-size:22px;color:#fff;text-shadow:0 1px 6px #0009}
.cx-badge{background:#1a1a1a;color:#fff;border-radius:0;letter-spacing:.15em}
.cx-others a{border-bottom:1px solid #1a1a1a;color:#1a1a1a;font-family:"Shippori Mincho B1",serif;padding:4px 2px;margin-right:10px}.cx-others a:hover{color:#f0643f}.cx-others strong{font-size:11px;letter-spacing:.3em;color:#f0643f}
@media (max-width:560px){.cx-feature{grid-template-columns:1fr;gap:8px}.cx-vol{border:0;padding:0;text-align:left}.cx-vol b{font-size:44px}}
